+// Register records a repository's configuration.
+//
+// Keyed by full name so a lookup can be served without the caller having
+// to resolve which forge the request arrived from.
+func (r *Registry) Register(ctx context.Context, forge Forge, fullName string, cfg RepoConfig) error {
+	return r.store.Put(ctx, fullName, cfg)
+}
+
+// Lookup returns the configuration registered for fullName.
+func (r *Registry) Lookup(ctx context.Context, fullName string) (RepoConfig, error) {
+	cfg, err := r.store.Get(ctx, fullName)
+	if err != nil {
+		return RepoConfig{}, err
+	}
+	return cfg, nil
 }
